import cv2
import numpy as np

def solve(text, max_width, scale, thickness) -> dict:
    # Get the width of a string in the specified font
    def text_width(s):
        (w, h), baseline = cv2.getTextSize(s, cv2.FONT_HERSHEY_SIMPLEX, scale, thickness)
        return w

    # Split text into words
    words = text.split(' ')

    # Handle empty text
    if not words or text == '':
        return {'lines': []}

    # Filter out empty strings that might result from multiple spaces, 
    # but the problem says "words separated by single spaces", so we assume no empty strings
    # However, let's be safe and remove empty strings if any
    words = [w for w in words if w != '']

    if not words:
        return {'lines': []}

    lines = []
    current_line = ''

    for word in words:
        # Check if the word alone is wider than max_width
        if text_width(word) > max_width:
            # If we have a current line, push it
            if current_line:
                lines.append(current_line)
                current_line = ''
            # The over-long word gets its own line
            lines.append(word)
            continue

        # Try to add the word to the current line
        if current_line == '':
            current_line = word
        else:
            # Check if adding " word" fits
            candidate = current_line + ' ' + word
            if text_width(candidate) <= max_width:
                current_line = candidate
            else:
                # Push current line and start new one with this word
                lines.append(current_line)
                current_line = word

    # Don't forget the last line
    if current_line:
        lines.append(current_line)

    return {'lines': lines}
