def total_product_quantity(stores_inventory):
    """
    Computes the total quantity of each product across multiple stores.

    :param stores_inventory: A dictionary of dictionaries where the outer dictionary keys are store names
                             and the inner dictionary keys are product names with their quantities as values.
    :return: A dictionary with product names as keys and their total quantities across all stores as values.
    """
    total_quantities = {}

    for store, products in stores_inventory.items():
        for product, quantity in products.items():
            if product in total_quantities:
                total_quantities[product] += quantity
            else:
                total_quantities[product] = quantity

    return total_quantities
