def sum_primes(n):
    """
    Computes the sum of all prime numbers between 1 and n (inclusive).

    :param n: An integer representing the upper limit.
    :return: The sum of all prime numbers between 1 and n.
    """
    if n < 2:
        return 0

    is_prime = [True] * (n + 1)
    p = 2

    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    return sum(p for p in range(2, n + 1) if is_prime[p])
