def get_nested_metadata(metadata, key, default=None):
    """
    Retrieves the value associated with a specified key from a nested dictionary.

    :param metadata: A dictionary containing the HTTP request metadata.
    :param key: A string representing the key to the required metadata (can be nested, separated by dots).
    :param default: An optional default value to return if the key is not found.
    :return: The value associated with the specified key, or the default value if the key is not found.
    """
    keys = key.split('.')
    current_level = metadata

    for k in keys:
        if isinstance(current_level, dict) and k in current_level:
            current_level = current_level[k]
        else:
            return default

    return current_level

# Example usage:
http_metadata = {
    'user': {
        'name': 'John Doe',
        'age': 30,
        'contact': {
            'email': 'john.doe@example.com'
        }
    },
    'request': {
        'method': 'GET',
