def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary, concatenating keys to create a single-level dictionary.
    Keys are concatenated with a specified separator (default: '.').

    :param d: The dictionary to flatten.
    :param parent_key: The base key string for recursion (used internally).
    :param sep: The separator between keys.
    :return: A new dictionary with flattened keys and original values.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

# Example usage:
