import cv2
import numpy as np

def solve(text, max_width, scale, thickness) -> dict:
    # Greedy word wrap: break text into lines so each line's rendered width <= max_width
    # Use cv2.getTextSize to measure width of each candidate line

    words = text.split(' ')

    def line_width(line: str) -> int:
        (w, h), baseline = cv2.getTextSize(line, cv2.FONT_HERSHEY_SIMPLEX, scale, thickness)
        return w

    lines = []
    current_line = ""

    for word in words:
        if not word:
            continue
        # Try adding this word to current line
        if current_line == "":
            # First word in line
            candidate = word
        else:
            candidate = current_line + " " + word

        if line_width(candidate) <= max_width:
            current_line = candidate
        else:
            # Current line is full, push it and start new line with this word
            if current_line:
                lines.append(current_line)
            # Start new line with this word (even if single word exceeds max_width)
            current_line = word

    if current_line:
        lines.append(current_line)

    return {'lines': lines}
