def merge_and_sort_word_frequencies(dict_list):
    """
    Merges multiple word frequency dictionaries and returns a sorted list of tuples
    containing words and their frequencies.

    :param dict_list: List of dictionaries, each containing word frequency data.
    :return: List of tuples (word, frequency) sorted by frequency (descending) and lexicographically.
    """
    merged_dict = {}

    for d in dict_list:
        for word, data in d.items():
            if word not in merged_dict:
                merged_dict[word] = {'frequency': 0, 'last_seen': [], 'following_words': {}}

            merged_dict[word]['frequency'] += data['frequency']
            merged_dict[word]['last_seen'].extend(data['last_seen'])

            for following_word, count in data['following_words'].items():
                if following_word not in merged_dict[word]['following_words']:
                    merged_dict[word]['following_words'][following_word] = 0
                merged_dict[word]['following_words'][following_word] += count

    return sorted([(word, data['frequency']) for word, data in merged_dict.items()],
                  key=lambda x: (-x[1], x[0]))
```

