class SimpleDatabase:
    def __init__(self):
        self.database = {}

    def add_record(self, record_id, name, age):
        """
        Adds a new record to the database with the given ID, name, and age.
        If the record ID already exists, prints a message indicating the record already exists.
        """
        if record_id in self.database:
            print(f"Record with ID {record_id} already exists.")
        else:
            self.database[record_id] = {'name': name, 'age': age}
            print(f"Record added: ID {record_id}, Name: {name}, Age: {age}")

    def delete_record(self, record_id):
        """
        Deletes a record from the database by its ID.
        If the record ID does not exist, prints a message indicating the record was not found.
        """
        if record_id in self.database:
            del self.database[record_id]
            print(f"Record with ID {record_id} has been deleted.")
        else:
            print(f"Record with ID {record_id} not found.")

    def retrieve_record(self, record_id):
        """
        Retrieves and prints a record from the database by its ID.
        If the record ID does not exist, prints a message indicating the record was not found.
        Returns the record if found, otherwise returns None.
        """
        record = self.database.get(record_id)
        if record:
            print(f"Record found - ID: {record_id}, Name: {record['name']}, Age: {record['age']}")
            return record
        else:
            print(f"Record with ID {record_id} not found.")
            return None

    def __str__(self):
        return str(self.database)

