def swap_keys_values(input_dict):
    """
    Swaps the keys and values of the given dictionary.
    If there are duplicate values, the keys are stored in a list.

    :param input_dict: Dictionary with unique keys
    :return: Dictionary with swapped keys and values
    """
    swapped_dict = {}
    for key, value in input_dict.items():
        if value not in swapped_dict:
            swapped_dict[value] = [key]
