        if item_id in self.items:
            return f"Stock of {self.items[item_id]['name']}: {self.items[item_id]['quantity']}"
        else:
            return "Item not found in inventory."

    def list_inventory(self):
        """
        Lists all items in the inventory in a formatted string.

        :return: Formatted string representation of all items in the inventory.
        """
        if self.items:
            inventory_list = "\nInventory List:\n"
            for item_id, details in self.items.items():
                inventory_list += f"ID: {item_id}, Name: {details['name']}, Price: ${details['price']}, Quantity: {details['quantity']}\n"
            return inventory_list
        else:
            return "Inventory is empty."
