import numpy as np

def solve(img, templ, method) -> dict:
    if method == 'sqdiff':
        method_flag = cv2.TM_SQDIFF_NORMED
    elif method == 'ccoeff':
        method_flag = cv2.TM_CCOEFF_NORMED
    else:
        raise ValueError(f"Unknown method: {method}")

    result = cv2.matchTemplate(img, templ, method_flag)
    h, w = templ.shape

    if method == 'sqdiff':
        min_val, _, min_loc, _ = cv2.minMaxLoc(result)
        best_x, best_y = min_loc
        score = float(min_val)
    else:
        _, max_val, _, max_loc = cv2.minMaxLoc(result)
        best_x, best_y = max_loc
        score = float(max_val)

    center = (best_x + w // 2, best_y + h // 2)

    return {
        'center': center,
        'score': score
    }
