import cv2
import numpy as np

def solve(gray) -> dict:
    # Create MSER detector with min_diversity to get regions
    mser = cv2.MSER_create(min_diversity=0.0)
    regions, bboxes = mser.detectRegions(gray)

    # regions shape: (N, 1, 1) in OpenCV 4.x, (N, 1) in 5.0
    # bboxes shape: (N, 4)
    if len(regions.shape) == 3:
        regions = regions.reshape(-1)
    else:
        regions = regions.reshape(-1)

    # Compute centers from bounding boxes
    if len(bboxes) == 0:
        return {'count': 0, 'centers': np.zeros((0, 2), dtype=np.float64)}

    # bboxes are [x, y, w, h]
    centers = np.column_stack([
        bboxes[:, 0] + bboxes[:, 2] / 2.0,
        bboxes[:, 1] + bboxes[:, 3] / 2.0
    ]).astype(np.float64)

    # Collapse nested regions: box centres closer than 6 px
    # Use a simple greedy approach: sort by area (largest first), keep if no already-kept center is within 6 px
    areas = bboxes[:, 2] * bboxes[:, 3]
    order = np.argsort(-areas)  # largest area first

    kept = []
    for idx in order:
        cx, cy = centers[idx]
        is_near = False
        for kx, ky in kept:
            if np.sqrt((cx - kx)**2 + (cy - ky)**2) < 6.0:
                is_near = True
                break
        if not is_near:
            kept.append((cx, cy))

    # Sort by x coordinate
    if len(kept) == 0:
        return {'count': 0, 'centers': np.zeros((0, 2), dtype=np.float64)}

    kept_arr = np.array(kept, dtype=np.float64)
    kept_arr = kept_arr[np.argsort(kept_arr[:, 0])]

    return {'count': len(kept_arr), 'centers': kept_arr}
