def FibonacciSum(n):
    """
    Calculate the sum of the first n terms in the Fibonacci sequence using recursion.

    Parameters:
    n (int): The number of terms in the Fibonacci sequence to sum.

    Returns:
    int: The sum of the first n Fibonacci numbers.

    Raises:
    ValueError: If n is less than 1.
    TypeError: If n is not an integer.
    """
    if not isinstance(n, int):
        raise TypeError("n must be type int")
    if n < 1:
        raise ValueError("n must be positive")

    def fibonacci_recursive(k):
        if k <= 0:
            return 0
        elif k == 1:
            return 1
        else:
            return fibonacci_recursive(k - 1) + fibonacci_recursive(k - 2)

    total_sum = sum(fibonacci_recursive(i) for i in range(1, n + 1))
    return total_sum
