class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a value into the BST."""
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        """Helper function to insert a value into the BST."""
        if key < node.val:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert(node.right, key)

    def delete(self, key):
        """Delete a value from the BST."""
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        """Helper function to delete a value from the BST."""
        if node is None:
            return node

        if key < node.val:
            node.left = self._delete(node.left, key)
        elif key > node.val:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            node.val = self._min_value_node(node.right).val
            node.right = self._delete(node.right, node.val)

        return node

    def find_min(self):
        """Find and return the minimum value in the BST."""
        if self.root is None:
            return None
        return self._min_value_node(self.root).val

    def _min_value_node(self, node):
        """Helper function to find the minimum value node in the BST."""
        current = node
        while current.left is not None:
            current = current.left
        return current

    def find_max(self):
        """Find and return the maximum value in the BST."""
        if self.root is None:
            return None
        return self._max_value_node(self.root).val

    def _max_value_node(self, node):
        """Helper function to find the maximum value node in the BST."""
        current = node
        while current.right is not None:
            current = current.right
        return current
