import random

def modular_exponentiation(base, exponent, modulus):
    """Compute (base^exponent) % modulus using an efficient method."""
    result = 1
    base = base % modulus
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % modulus
        exponent = exponent >> 1
        base = (base * base) % modulus
    return result

def miller_rabin_test(d, n):
    """Return True if n is a probable prime in the Miller-Rabin test with parameter d."""
    a = 2 + random.randint(1, n - 4)
    x = modular_exponentiation(a, d, n)
    if x == 1 or x == n - 1:
        return True
    while d != n - 1:
        x = (x * x) % n
        d *= 2
        if x == 1:
            return False
        if x == n - 1:
            return True
    return False

def is_probable_prime(n, k):
    """Check whether n is a probable prime with k tests."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False
    d = n - 1
    while d % 2 == 0:
        d //= 2
    for _ in range(k):
        if not miller_rabin_test(d, n):
            return False
    return True
