def group_words_by_length(word_dict):
    """
    Groups words by their length, excluding words with non-alphabetic characters.

    Parameters:
    word_dict (dict): A dictionary with words as keys and positive integers as values.

    Returns:
    dict: A dictionary with word lengths as keys and sorted lists of words as values.
    """
    grouped_dict = {}

    for word, count in word_dict.items():
        if word.isalpha():
            word_length = len(word)
            if word_length not in grouped_dict:
                grouped_dict[word_length] = []
            grouped_dict[word_length].append(word)

    for length, words in grouped_dict.items():
        grouped_dict[length] = sorted(words)

    return grouped_dict
